      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-auth-in-one\",\n  \"version\": \"0.2.0-alpha.4\",\n  \"description\": \"Self-contained DeepSeek Harness plugin for Provider login, model switching, image fallback, usage analytics, and same-port Web restart\",\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh-plugin\",\n    \"openai-codex\",\n    \"oauth\",\n    \"device-code\",\n    \"provider-authentication\",\n    \"llm-provider\",\n    \"openai-compatible\",\n    \"custom-api\",\n    \"model-switching\",\n    \"token-usage\",\n    \"cost-tracking\",\n    \"usage-analytics\",\n    \"vision-fallback\",\n    \"multimodal\",\n    \"image-understanding\",\n    \"text-only-model\",\n    \"usage-attribution\",\n    \"cost-attribution\",\n    \"self-contained-installer\",\n    \"same-port-restart\"\n  ],\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"bin\": {\n    \"dsh-auth-in-one\": \"lib/install.js\"\n  },\n  \"types\": \"lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./host\": {\n      \"types\": \"./lib/types/host/index.d.ts\",\n      \"default\": \"./lib/host.js\"\n    },\n    \"./types\": {\n      \"types\": \"./lib/types/types.d.ts\",\n      \"default\": \"./lib/types.js\"\n    },\n    \"./typert\": {\n      \"types\": \"./lib/types/generated/host.d.ts\",\n      \"default\": \"./lib/typert.host.js\"\n    },\n    \"./remote\": {\n      \"types\": \"./lib/types/generated/remote.d.ts\",\n      \"default\": \"./lib/typert.remote-client.js\"\n    },\n    \"./client\": \"./lib/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib/index.js\",\n    \"lib/host.js\",\n    \"lib/install.js\",\n    \"lib/anthropic.js\",\n    \"lib/github-copilot.js\",\n    \"lib/xai.js\",\n    \"lib/types.js\",\n    \"lib/typert.host.js\",\n    \"lib/typert.remote-client.js\",\n    \"lib/node-shared*.js\",\n    \"lib/client.js\",\n    \"lib/client.js.map\",\n    \"lib/types/**/*.d.ts\",\n    \"lib/types/**/*.d.ts.map\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.zh-CN.md\",\n    \"THIRD_PARTY_NOTICES.md\",\n    \"LICENSE\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-api-remotes\",\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-runtime\",\n        \"@deepseek-ai/dsh-client-schema-form\",\n        \"@deepseek-ai/dsh-client-ui-primitives\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-sidebar\",\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"@deepseek-ai/dsh-client-web-react\",\n        \"@deepseek-ai/dsh-client-locale\"\n      ]\n    }\n  },\n  \"scripts\": {\n    \"generate:typert\": \"node build/generate-typert.mjs\",\n    \"build\": \"pnpm generate:typert && tsc -p tsconfig.host.json && tsc -p tsconfig.client.json && node build/clean-bundle-chunks.mjs && tsdown --config build/tsdown.config.mjs && node build/normalize-artifacts.mjs\",\n    \"typecheck\": \"tsc -p tsconfig.host.json --noEmit && tsc -p tsconfig.client.json --noEmit\",\n    \"verify:boundaries\": \"node build/verify-boundaries.mjs\",\n    \"test\": \"vitest run\",\n    \"test:watch\": \"vitest\"\n  },\n  \"license\": \"MIT\",\n  \"author\": \"Stormycry-cryp\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Stormycry-cryp/dsh-AuthInOne.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/Stormycry-cryp/dsh-AuthInOne/issues\"\n  },\n  \"dependencies\": {\n    \"clsx\": \"^2.1.1\",\n    \"zod\": \"^4.4.3\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \">=4.0.1\",\n    \"@deepseek-ai/dsh-agent-default-model\": \">=0.1.0-rc.5\",\n    \"@deepseek-ai/dsh-api-remotes\": \">=0.1.0-rc.5\",\n    \"@deepseek-ai/dsh-attachment\": \">=0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-locale\": \">=0.1.0-rc.5\",\n    \"@deepseek-ai/dsh-client-connection\": \">=0.1.0-rc.5\",\n    \"@deepseek-ai/dsh-client-runtime\": \">=0.1.0-rc.5\",\n    \"@deepseek-ai/dsh-client-schema-form\": \">=0.1.0-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \">=0.1.0-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \">=0.1.0-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-sidebar\": \">=0.1.0-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \">=0.1.0-rc.5\",\n    \"@deepseek-ai/dsh-client-web-react\": \">=0.1.0-rc.5\",\n    \"@deepseek-ai/dsh-credentials\": \">=0.1.0-rc.5\",\n    \"@deepseek-ai/dsh-llm\": \">=0.1.0-rc.5\",\n    \"@deepseek-ai/dsh-llm-pi-ai\": \">=0.1.0-rc.5\",\n    \"@deepseek-ai/dsh-session\": \">=0.1.0-rc.5\",\n    \"@deepseek-ai/dsh-session-persistence\": \">=0.1.0-rc.5\",\n    \"@deepseek-ai/dsh-settings\": \">=0.1.0-rc.5\",\n    \"@deepseek-ai/dsh-typert-protocol\": \">=0.1.0-rc.5\",\n    \"@deepseek-ai/schemastery\": \">=3.18.1\",\n    \"react\": \">=18.2.0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-agent-default-model\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-api-remotes\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-attachment\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-locale\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-connection\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-runtime\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-schema-form\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-primitives\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-settings\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-sidebar\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-slots\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-web-react\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-credentials\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-llm\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-llm-pi-ai\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-session\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-session-persistence\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-settings\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-typert-protocol\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/schemastery\": {\n      \"optional\": true\n    },\n    \"react\": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"@cursor/sdk\": \"1.0.24\",\n    \"@deepseek-ai/dsh-typert-generator\": \">=0.1.0-rc.5\",\n    \"@earendil-works/pi-ai\": \"^0.82.1\",\n    \"@testing-library/react\": \"^16.1.0\",\n    \"@types/node\": \"^24.0.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"~18.3.1\",\n    \"happy-dom\": \"20.11.2\",\n    \"lightningcss\": \"^1.30.2\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\",\n    \"tsdown\": \"^0.21.0\",\n    \"typescript\": \"^6.0.3\",\n    \"vitest\": \"^3.2.4\"\n  },\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24\"\n  },\n  \"packageManager\": \"pnpm@11.19.0\"\n}\n"
