      "path": "src/host/auth.ts",
      "content": "/** Host-only account login coordination and DSH adapter activation. */\n\nimport { randomUUID } from 'node:crypto'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { AdapterRegistrationHandle, LlmAdapter } from '@deepseek-ai/dsh-llm'\nimport { resolveRetryPolicy } from '@deepseek-ai/dsh-llm'\nimport { PiAiAdapter, type ResolvedPiAiProviderProfile } from '@deepseek-ai/dsh-llm-pi-ai'\nimport { openaiCodexProvider } from '@earendil-works/pi-ai/providers/openai-codex'\nimport { createProvider, type Model, type Provider } from '@earendil-works/pi-ai'\nimport * as openAICompletionsApi from '@earendil-works/pi-ai/api/openai-completions'\nimport { anthropicProvider } from '@earendil-works/pi-ai/providers/anthropic'\nimport { githubCopilotProvider } from '@earendil-works/pi-ai/providers/github-copilot'\nimport { xaiProvider } from '@earendil-works/pi-ai/providers/xai'\nimport type { AuthErrorCategory, AuthProviderView, CodexUsageView, ProviderQuotaView } from '../types.ts'\nimport { AuthProtocolError, OpenAICodexOAuthAdapter, type AuthProviderAdapter } from './auth-protocol.ts'\nimport { DshOAuthCredentialStore } from './auth-store.ts'\nimport { CODEX_USAGE_SOURCE, fetchCodexUsage } from './codex-usage.ts'\nimport { KIMI_AUTH_SOURCE, KimiCodeDeviceAdapter } from './kimi-auth-protocol.ts'\nimport { KIMI_USAGE_SOURCE, fetchKimiUsage } from './kimi-usage.ts'\nimport { PiOAuthBridgeAdapter, type BridgeOAuthAuth } from './pi-oauth-bridge.ts'\nimport { CommandCodeCompatibilityAdapter, CursorCompatibilityAdapter } from './compat-auth-protocols.ts'\nimport { GOOGLE_ANTIGRAVITY_AUTH_SOURCE, GoogleAntigravityCompatibilityAdapter } from './google-antigravity-auth.ts'\nimport { KIRO_AUTH_SOURCE, KiroDeviceCompatibilityAdapter } from './kiro-auth-protocol.ts'\nimport { CommandCodeLlmAdapter } from './command-code-adapter.ts'\nimport { KiroLlmAdapter } from './kiro-llm-adapter.ts'\nimport { GoogleAntigravityLlmAdapter } from './google-antigravity-adapter.ts'\nimport { CursorSdkLlmAdapter } from './cursor-sdk-adapter.ts'\n\nexport const OPENAI_CODEX_PROVIDER = 'openai-codex'\nexport const KIMI_CODE_PROVIDER = 'kimi-code'\nexport const XAI_PROVIDER = 'xai'\nexport const ANTHROPIC_PROVIDER = 'anthropic'\nexport const GITHUB_COPILOT_PROVIDER = 'github-copilot'\nexport const COMMAND_CODE_PROVIDER = 'command-code'\nexport const CURSOR_PROVIDER = 'cursor'\nexport const GOOGLE_ANTIGRAVITY_PROVIDER = 'google-antigravity'\nexport const KIRO_PROVIDER = 'kiro'\nconst OPENAI_CODEX_AUTH_SOURCE = 'https://github.com/openai/codex/blob/main/codex-rs/app-server/README.md#auth-endpoints'\n\nfunction unavailableAuth(\n  id: string,\n  name: string,\n  method: AuthProviderView['method'],\n  stability: AuthProviderView['stability'],\n  sourceUrl: string,\n  availabilityReason: NonNullable<AuthProviderView['availabilityReason']>,\n): AuthProviderView {\n  return {\n    id,\n    name,\n    method,\n    official: true,\n    available: false,\n    stability,\n    sourceUrl,\n    availabilityReason,\n    status: 'signed-out',\n    authorizationUrl: null,\n    verificationUrl: null,\n    userCode: null,\n    inputPrompt: null,\n    attemptId: null,\n    expiresAt: null,\n    accountLabel: null,\n    errorCategory: null,\n    error: null,\n  }\n}\n\n/** Official-source parity entries that deliberately fail closed in this release. */\nexport const UNAVAILABLE_AUTH_PROVIDERS: readonly AuthProviderView[] = [\n  unavailableAuth('qwen', 'Qwen', 'device-code', 'unsupported', 'https://github.com/QwenLM/qwen-code/blob/main/docs/users/configuration/auth.md', 'discontinued'),\n]\n\nfunction maskEmail(email: string | undefined): string | null {\n  if (email === undefined) return null\n  const at = email.indexOf('@')\n  if (at <= 0) return null\n  const local = email.slice(0, at)\n  const visible = local.length <= 2 ? local.slice(0, 1) : `${local[0]}***${local.at(-1)}`\n  return `${visible}${email.slice(at)}`\n}\n\nfunction maskAccount(accountId: string | undefined): string | null {\n  if (accountId === undefined) return null\n  return accountId.length <= 4 ? 'account-…' : `account-…${accountId.slice(-4)}`\n}\n\ninterface PendingAttempt {\n  readonly id: string\n  readonly controller: AbortController\n  cancelled: boolean\n}\n\n/** Minimal login engine surface, injectable for state-machine tests. */\nexport interface CodexAuthEngine {\n  status(): Promise<{ connected: boolean; needsReauth: boolean; accountLabel: string | null }>\n  login(signal: AbortSignal, onReady: (ready: {\n    authorizationUrl: string\n    verificationUrl?: string\n    userCode?: string\n    inputPrompt?: {\n      kind: 'authorization-code'\n      label: string\n      placeholder?: string\n    }\n    expiresAt: number\n  }) => void): Promise<string | null>\n  submit?(value: string): void\n  logout(signal?: AbortSignal): Promise<{ revocationError?: AuthProtocolError }>\n}\n\n/** Public identity and risk label for one Host-owned Auth transaction. */\nexport interface AuthCoordinatorDescriptor {\n  readonly id: string\n  readonly name: string\n  readonly method: AuthProviderView['method']\n  readonly stability: AuthProviderView['stability']\n  readonly sourceUrl: string\n  readonly official?: boolean\n}\n\n/** Browser OAuth state machine that never exposes an OAuth credential. */\nexport class CodexAuthCoordinator {\n  private attempt: PendingAttempt | undefined\n  private state: AuthProviderView\n\n  constructor(\n    private readonly engine: CodexAuthEngine,\n    private readonly onConnected: () => void,\n    private readonly onDisconnected: () => void,\n    private readonly descriptor: AuthCoordinatorDescriptor = {\n      id: OPENAI_CODEX_PROVIDER,\n      name: 'OpenAI Codex',\n      method: 'browser-oauth',\n      stability: 'stable',\n      sourceUrl: OPENAI_CODEX_AUTH_SOURCE,\n    },\n  ) {\n    this.state = this.view('signed-out')\n  }\n\n  private view(\n    status: AuthProviderView['status'],\n    fields: Partial<Omit<AuthProviderView, 'id' | 'name' | 'method' | 'official' | 'status'>> = {},\n  ): AuthProviderView {\n    return {\n      id: this.descriptor.id,\n      name: this.descriptor.name,\n      method: this.descriptor.method,\n      official: this.descriptor.official ?? true,\n      available: true,\n      stability: this.descriptor.stability,\n      sourceUrl: this.descriptor.sourceUrl,\n      availabilityReason: null,\n      status,\n      authorizationUrl: null,\n      verificationUrl: null,\n      userCode: null,\n      inputPrompt: null,\n      attemptId: null,\n      expiresAt: null,\n      accountLabel: null,\n      errorCategory: null,\n      error: null,\n      ...fields,\n    }\n  }\n\n  snapshot(): AuthProviderView {\n    return { ...this.state }\n  }\n\n  private failure(error: unknown): { category: AuthErrorCategory; message: string } {\n    const protocol = error instanceof AuthProtocolError ? error : new AuthProtocolError('network')\n    return { category: protocol.category, message: protocol.message }\n  }\n\n  async synchronize(): Promise<AuthProviderView> {\n    if (this.attempt !== undefined) return this.snapshot()\n    try {\n      const current = await this.engine.status()\n      if (current.needsReauth) {\n        this.onDisconnected()\n        this.state = this.view('needs-reauth', { accountLabel: current.accountLabel })\n      } else if (current.connected) {\n        this.onConnected()\n        this.state = this.view('connected', { accountLabel: current.accountLabel })\n      } else {\n        this.onDisconnected()\n        this.state = this.view('signed-out')\n      }\n    } catch (error) {\n      const failure = this.failure(error)\n      this.onDisconnected()\n      this.state = this.view('error', { errorCategory: failure.category, error: failure.message })\n    }\n    return this.snapshot()\n  }\n\n  async start(): Promise<AuthProviderView> {\n    if (this.state.status === 'connected') return this.snapshot()\n    if (this.attempt !== undefined) return this.snapshot()\n    const attempt: PendingAttempt = { id: randomUUID(), controller: new AbortController(), cancelled: false }\n    this.attempt = attempt\n    this.state = this.view('starting', { attemptId: attempt.id })\n\n    let resolveReady!: (view: AuthProviderView) => void\n    let rejectReady!: (error: unknown) => void\n    let readySettled = false\n    const ready = new Promise<AuthProviderView>((resolve, reject) => {\n      resolveReady = resolve\n      rejectReady = reject\n    })\n    void this.engine.login(attempt.controller.signal, ready => {\n      if (this.attempt !== attempt) return\n      this.state = this.view('pending', {\n        authorizationUrl: ready.authorizationUrl,\n        verificationUrl: ready.verificationUrl ?? null,\n        userCode: ready.userCode ?? null,\n        inputPrompt: ready.inputPrompt === undefined ? null : {\n          kind: ready.inputPrompt.kind,\n          label: ready.inputPrompt.label,\n          placeholder: ready.inputPrompt.placeholder ?? null,\n        },\n        attemptId: attempt.id,\n        expiresAt: ready.expiresAt,\n      })\n      if (!readySettled) {\n        readySettled = true\n        resolveReady(this.snapshot())\n      }\n    }).then(accountLabel => {\n      if (this.attempt !== attempt) return\n      this.attempt = undefined\n      if (attempt.cancelled) return\n      this.onConnected()\n      this.state = this.view('connected', { accountLabel })\n      if (!readySettled) {\n        readySettled = true\n        resolveReady(this.snapshot())\n      }\n    }, error => {\n      if (this.attempt !== attempt) return\n      this.attempt = undefined\n      const failure = this.failure(error)\n      const status = attempt.cancelled || failure.category === 'cancelled'\n        ? 'cancelled'\n        : failure.category === 'expired' ? 'expired' : 'error'\n      this.state = this.view(status, { errorCategory: failure.category, error: failure.message })\n      if (!readySettled) {\n        readySettled = true\n        rejectReady(error)\n      }\n    })\n    return ready\n  }\n\n  cancel(attemptId: string): AuthProviderView {\n    const attempt = this.attempt\n    if (attempt === undefined || attempt.id !== attemptId) return this.snapshot()\n    attempt.cancelled = true\n    attempt.controller.abort()\n    this.state = this.view('cancelled', {\n      errorCategory: 'cancelled',\n      error: new AuthProtocolError('cancelled').message,\n    })\n    return this.snapshot()\n  }\n\n  /** Submit one bounded one-time authorization value to the active Host transaction. */\n  submit(attemptId: string, value: string): AuthProviderView {\n    const attempt = this.attempt\n    if (attempt === undefined || attempt.id !== attemptId || this.engine.submit === undefined) {\n      throw new AuthProtocolError('invalid-response')\n    }\n    const trimmed = value.trim()\n    if (trimmed.length === 0 || trimmed.length > 16 * 1024) throw new AuthProtocolError('invalid-response')\n    this.engine.submit(trimmed)\n    return this.snapshot()\n  }\n\n  async logout(): Promise<AuthProviderView> {\n    const attempt = this.attempt\n    if (attempt !== undefined) {\n      attempt.cancelled = true\n      attempt.controller.abort()\n      this.attempt = undefined\n    }\n    const outcome = await this.engine.logout()\n    this.onDisconnected()\n    this.state = outcome.revocationError === undefined\n      ? this.view('signed-out')\n      : this.view('signed-out', {\n          errorCategory: outcome.revocationError.category,\n          error: outcome.revocationError.message,\n        })\n    return this.snapshot()\n  }\n}\n\n/** Runtime bridge: the plugin owns OAuth while pi-ai supplies Codex transport and model metadata. */\nexport class OpenAICodexAuthRuntime {\n  readonly coordinator: CodexAuthCoordinator\n  readonly models: readonly { id: string; name: string }[]\n  private readonly adapter: AuthProviderAdapter\n  private readonly credentials: DshOAuthCredentialStore\n  private registration: AdapterRegistrationHandle | undefined\n  private disposed = false\n\n  constructor(ctx: Context, oauth: AuthProviderAdapter = new OpenAICodexOAuthAdapter()) {\n    this.adapter = oauth\n    this.credentials = new DshOAuthCredentialStore(ctx)\n    const nativeProvider = openaiCodexProvider()\n    const piProvider = {\n      ...nativeProvider,\n      auth: {\n        ...nativeProvider.auth,\n        apiKey: {\n          name: 'DSH-managed OpenAI Codex OAuth',\n          resolve: ({ credential }: { credential?: { key?: string } }) => Promise.resolve(\n            credential?.key === undefined ? undefined : { auth: { apiKey: credential.key }, source: 'DSH OAuth' },\n          ),\n        },\n      },\n    }\n    const profile: ResolvedPiAiProviderProfile = {\n      provider: OPENAI_CODEX_PROVIDER,\n      displayName: 'OpenAI Codex',\n      streamIdleTimeoutMs: 120_000,\n      retryPolicy: resolveRetryPolicy(undefined, 'auth-in-one OpenAI Codex retryPolicy'),\n      configuredMaxTokens: new Map(),\n      piProvider,\n    }\n    const profiles = new Map([[OPENAI_CODEX_PROVIDER, profile]])\n    this.models = profile.piProvider.getModels().map(model => ({ id: model.id, name: model.name }))\n    const transport = new PiAiAdapter({\n      profiles: () => profiles,\n      resolveApiKey: async () => {\n        try {\n          return await this.credentials.accessToken(this.adapter)\n        } catch (error) {\n          if (error instanceof AuthProtocolError && error.category === 'refresh-rejected') this.deactivate()\n          throw error\n        }\n      },\n    })\n    const activate = (): void => {\n      if (this.disposed || this.registration !== undefined) return\n      this.registration = ctx.llm.registerAdapter([OPENAI_CODEX_PROVIDER], transport)\n    }\n    this.coordinator = new CodexAuthCoordinator({\n      status: async () => {\n        const status = await this.credentials.status()\n        return {\n          connected: status.connected,\n          needsReauth: status.needsReauth,\n          accountLabel: maskEmail(status.email) ?? maskAccount(status.accountId),\n        }\n      },\n      login: async (signal, onReady) => {\n        const handle = await this.adapter.start(signal)\n        onReady({\n          authorizationUrl: handle.authorizationUrl,\n          ...handle.verificationUrl === undefined ? {} : { verificationUrl: handle.verificationUrl },\n          ...handle.userCode === undefined ? {} : { userCode: handle.userCode },\n          expiresAt: handle.expiresAt,\n        })\n        const credential = await handle.completion\n        if (signal.aborted) throw new AuthProtocolError('cancelled')\n        await this.credentials.write(credential)\n        if (signal.aborted) {\n          await this.credentials.delete()\n          throw new AuthProtocolError('cancelled')\n        }\n        return maskEmail(credential.email) ?? maskAccount(credential.accountId)\n      },\n      logout: async signal => {\n        const credential = await this.credentials.read()\n        await this.credentials.delete()\n        let revocationError: AuthProtocolError | undefined\n        if (credential !== undefined) {\n          try {\n            await this.adapter.revoke(credential, signal)\n          } catch (error) {\n            revocationError = error instanceof AuthProtocolError\n              ? error\n              : new AuthProtocolError('revocation-failed')\n          }\n        }\n        return revocationError === undefined ? {} : { revocationError }\n      },\n    }, activate, () => { this.deactivate() })\n  }\n\n  private deactivate(): void {\n    this.registration?.()\n    this.registration = undefined\n  }\n\n  /** Read best-effort subscription windows with the Host-only credential. */\n  async usage(signal?: AbortSignal): Promise<CodexUsageView> {\n    const credential = await this.credentials.read()\n    if (credential === undefined || credential.needsReauth === true) {\n      return {\n        status: 'signed-out',\n        generatedAt: Date.now(),\n        bestEffort: true,\n        sourceUrl: CODEX_USAGE_SOURCE,\n        windows: [],\n        error: null,\n      }\n    }\n    const accessToken = await this.credentials.accessToken(this.adapter, signal)\n    const current = await this.credentials.read()\n    return fetchCodexUsage(accessToken, current?.accountId, signal)\n  }\n\n  dispose(): void {\n    this.disposed = true\n    const pending = this.coordinator.snapshot().attemptId\n    if (pending !== null) this.coordinator.cancel(pending)\n    this.deactivate()\n  }\n}\n\nconst KIMI_MODELS: readonly Model<'openai-completions'>[] = [\n  {\n    id: 'k3', name: 'Kimi K3', api: 'openai-completions', provider: KIMI_CODE_PROVIDER,\n    baseUrl: 'https://api.kimi.com/coding/v1', reasoning: true, input: ['text', 'image'],\n    cost: { input: 3, output: 15, cacheRead: 0.3, cacheWrite: 0 }, contextWindow: 1_048_576, maxTokens: 131_072,\n  },\n  {\n    id: 'kimi-for-coding', name: 'Kimi for Coding', api: 'openai-completions', provider: KIMI_CODE_PROVIDER,\n    baseUrl: 'https://api.kimi.com/coding/v1', reasoning: true, input: ['text', 'image'],\n    cost: { input: 0.95, output: 4, cacheRead: 0.19, cacheWrite: 0 }, contextWindow: 262_144, maxTokens: 32_768,\n  },\n  {\n    id: 'kimi-for-coding-highspeed', name: 'Kimi for Coding HighSpeed', api: 'openai-completions', provider: KIMI_CODE_PROVIDER,\n    baseUrl: 'https://api.kimi.com/coding/v1', reasoning: true, input: ['text', 'image'],\n    cost: { input: 1.9, output: 8, cacheRead: 0.38, cacheWrite: 0 }, contextWindow: 262_144, maxTokens: 32_768,\n  },\n]\n\n/** Kimi Code device login, DSH credential lifecycle, and managed model route. */\nexport class KimiCodeAuthRuntime {\n  readonly coordinator: CodexAuthCoordinator\n  readonly models = KIMI_MODELS.map(model => ({ id: model.id, name: model.name }))\n  private readonly adapter: AuthProviderAdapter\n  private readonly credentials: DshOAuthCredentialStore\n  private registration: AdapterRegistrationHandle 