gin: async (signal, onReady) => {\n        const handle = await this.adapter.start(signal)\n        onReady({\n          authorizationUrl: handle.authorizationUrl,\n          ...handle.verificationUrl === undefined ? {} : { verificationUrl: handle.verificationUrl },\n          ...handle.userCode === undefined ? {} : { userCode: handle.userCode },\n          expiresAt: handle.expiresAt,\n        })\n        const stored = await handle.completion\n        if (signal.aborted) throw new AuthProtocolError('cancelled')\n        await this.credentials.write(stored)\n        if (signal.aborted) {\n          await this.credentials.delete()\n          throw new AuthProtocolError('cancelled')\n        }\n        return null\n      },\n      logout: async signal => {\n        const stored = await this.credentials.read()\n        await this.credentials.delete()\n        let revocationError: AuthProtocolError | undefined\n        if (stored !== undefined) {\n          try {\n            await this.adapter.revoke(stored, signal)\n          } catch {\n            revocationError = new AuthProtocolError('revocation-failed')\n          }\n        }\n        return revocationError === undefined ? {} : { revocationError }\n      },\n    }, activate, () => { this.deactivate() }, {\n      id: KIMI_CODE_PROVIDER,\n      name: 'Kimi Code 设备登录',\n      method: 'device-code',\n      stability: 'experimental',\n      sourceUrl: KIMI_AUTH_SOURCE,\n    })\n  }\n\n  private deactivate(): void {\n    this.registration?.()\n    this.registration = undefined\n  }\n\n  /** Read best-effort Kimi Code subscription windows with the Host-only credential. */\n  async quota(signal?: AbortSignal): Promise<ProviderQuotaView> {\n    const credential = await this.credentials.read()\n    if (credential === undefined || credential.needsReauth === true) {\n      return {\n        provider: KIMI_CODE_PROVIDER, status: 'signed-out', generatedAt: Date.now(), bestEffort: true,\n        sourceUrl: KIMI_USAGE_SOURCE, windows: [], error: null,\n      }\n    }\n    const accessToken = await this.credentials.accessToken(this.adapter, signal)\n    return fetchKimiUsage(accessToken, signal)\n  }\n\n  dispose(): void {\n    this.disposed = true\n    const pending = this.coordinator.snapshot().attemptId\n    if (pending !== null) this.coordinator.cancel(pending)\n    this.deactivate()\n  }\n}\n\n/** Shared DSH credential and model lifecycle for installed pi-ai OAuth protocols. */\nexport class SubscriptionAuthRuntime {\n  readonly coordinator: CodexAuthCoordinator\n  readonly models: readonly { id: string; name: string }[]\n  private readonly adapter: AuthProviderAdapter\n  private readonly credentials: DshOAuthCredentialStore\n  private registration: AdapterRegistrationHandle | undefined\n  private disposed = false\n\n  constructor(ctx: Context, options: {\n    readonly descriptor: AuthCoordinatorDescriptor\n    readonly credentialRef: string\n    readonly adapter?: AuthProviderAdapter\n    readonly piProvider?: Provider\n    readonly createTransport?: (\n      accessToken: (signal?: AbortSignal) => Promise<string>,\n      credential: () => Promise<import('./auth-protocol.ts').StoredOAuthCredential | undefined>,\n    ) => LlmAdapter\n  }) {\n    if (options.adapter === undefined && options.piProvider?.auth.oauth === undefined) {\n      throw new TypeError(`Auth runtime ${options.descriptor.id} requires an adapter or pi-ai OAuth`)\n    }\n    this.adapter = options.adapter ?? new PiOAuthBridgeAdapter(\n      options.descriptor.id,\n      options.descriptor.name,\n      options.piProvider!.auth.oauth as BridgeOAuthAuth,\n    )\n    this.credentials = new DshOAuthCredentialStore(ctx, options.credentialRef)\n    this.models = options.piProvider?.getModels().map(model => ({ id: model.id, name: model.name })) ?? []\n    const piProvider = options.piProvider\n    let transport: LlmAdapter | undefined\n    if (piProvider !== undefined) {\n    const profile: ResolvedPiAiProviderProfile = {\n      provider: options.descriptor.id,\n      displayName: options.descriptor.name,\n      streamIdleTimeoutMs: 120_000,\n      retryPolicy: resolveRetryPolicy(undefined, `auth-in-one ${options.descriptor.id} retryPolicy`),\n      configuredMaxTokens: new Map(),\n      piProvider,\n    }\n    const profiles = new Map([[options.descriptor.id, profile]])\n      transport = new PiAiAdapter({\n      profiles: () => profiles,\n      resolveApiKey: async () => {\n        try {\n          return await this.credentials.accessToken(this.adapter)\n        } catch (error) {\n          if (error instanceof AuthProtocolError && error.category === 'refresh-rejected') this.deactivate()\n          throw error\n        }\n      },\n    })\n    }\n    transport ??= options.createTransport?.(\n      async signal => this.credentials.accessToken(this.adapter, signal),\n      () => this.credentials.read(),\n    )\n    const activate = (): void => {\n      if (this.disposed || this.registration !== undefined || transport === undefined) return\n      this.registration = ctx.llm.registerAdapter([options.descriptor.id], transport)\n    }\n    let activeHandle: import('./auth-protocol.ts').AuthLoginHandle | undefined\n    this.coordinator = new CodexAuthCoordinator({\n      status: async () => {\n        const status = await this.credentials.status()\n        return { connected: status.connected, needsReauth: status.needsReauth, accountLabel: null }\n      },\n      login: async (signal, onReady) => {\n        const handle = await this.adapter.start(signal)\n        activeHandle = handle\n        onReady({\n          authorizationUrl: handle.authorizationUrl,\n          ...handle.verificationUrl === undefined ? {} : { verificationUrl: handle.verificationUrl },\n          ...handle.userCode === undefined ? {} : { userCode: handle.userCode },\n          ...handle.inputPrompt === undefined ? {} : { inputPrompt: handle.inputPrompt },\n          expiresAt: handle.expiresAt,\n        })\n        const stored = await handle.completion.finally(() => {\n          if (activeHandle === handle) activeHandle = undefined\n        })\n        if (signal.aborted) throw new AuthProtocolError('cancelled')\n        await this.credentials.write(stored)\n        if (signal.aborted) {\n          await this.credentials.delete()\n          throw new AuthProtocolError('cancelled')\n        }\n        return null\n      },\n      submit: value => {\n        if (activeHandle?.submit === undefined) throw new AuthProtocolError('invalid-response')\n        activeHandle.submit(value)\n      },\n      logout: async () => {\n        await this.credentials.delete()\n        return {}\n      },\n    }, activate, () => { this.deactivate() }, options.descriptor)\n  }\n\n  private deactivate(): void {\n    this.registration?.()\n    this.registration = undefined\n  }\n\n  /** Resolve this Provider's fresh Host-only access token for a plugin-owned auxiliary request. */\n  accessToken(signal?: AbortSignal): Promise<string> {\n    return this.credentials.accessToken(this.adapter, signal)\n  }\n\n  /** Read Provider-specific Host-only metadata for a plugin-owned auxiliary request. */\n  credential(): Promise<import('./auth-protocol.ts').StoredOAuthCredential | undefined> {\n    return this.credentials.read()\n  }\n\n  dispose(): void {\n    this.disposed = true\n    const pending = this.coordinator.snapshot().attemptId\n    if (pending !== null) this.coordinator.cancel(pending)\n    this.deactivate()\n  }\n}\n\n/** Create compatibility runtimes with one common DSH transaction and credential lifecycle. */\nexport function createCompatibilityAuthRuntimes(ctx: Context): readonly SubscriptionAuthRuntime[] {\n  return [\n    new SubscriptionAuthRuntime(ctx, {\n      descriptor: {\n        id: XAI_PROVIDER, name: 'xAI Grok', method: 'device-code', stability: 'experimental',\n        sourceUrl: 'https://github.com/xai-org/grok-build/blob/main/crates/codegen/xai-grok-pager/docs/user-guide/02-authentication.md',\n      },\n      credentialRef: 'DSH_AUTH_IN_ONE_XAI_OAUTH',\n      piProvider: xaiProvider(),\n    }),\n    new SubscriptionAuthRuntime(ctx, {\n      descriptor: {\n        id: ANTHROPIC_PROVIDER, name: 'Anthropic 登录兼容', method: 'browser-oauth', stability: 'experimental',\n        sourceUrl: 'https://github.com/anthropics/claude-code',\n        official: false,\n      },\n      credentialRef: 'DSH_AUTH_IN_ONE_ANTHROPIC_OAUTH',\n      piProvider: anthropicProvider(),\n    }),\n    new SubscriptionAuthRuntime(ctx, {\n      descriptor: {\n        id: GITHUB_COPILOT_PROVIDER, name: 'GitHub Copilot', method: 'device-code', stability: 'experimental',\n        sourceUrl: 'https://docs.github.com/en/copilot/how-tos/copilot-sdk/setup/github-oauth',\n      },\n      credentialRef: 'DSH_AUTH_IN_ONE_GITHUB_COPILOT_OAUTH',\n      piProvider: githubCopilotProvider(),\n    }),\n    new SubscriptionAuthRuntime(ctx, {\n      descriptor: {\n        id: COMMAND_CODE_PROVIDER, name: 'Command Code Auth', method: 'browser-oauth', stability: 'experimental',\n        sourceUrl: 'https://commandcode.ai/docs/quickstart',\n      },\n      credentialRef: 'DSH_AUTH_IN_ONE_COMMAND_CODE_AUTH',\n      adapter: new CommandCodeCompatibilityAdapter(),\n      createTransport: accessToken => new CommandCodeLlmAdapter(accessToken),\n    }),\n    new SubscriptionAuthRuntime(ctx, {\n      descriptor: {\n        id: CURSOR_PROVIDER, name: 'Cursor 登录兼容', method: 'browser-oauth', stability: 'experimental',\n        sourceUrl: 'https://docs.cursor.com/en/cli/reference/authentication',\n        official: false,\n      },\n      credentialRef: 'DSH_AUTH_IN_ONE_CURSOR_OAUTH',\n      adapter: new CursorCompatibilityAdapter(),\n      createTransport: accessToken => new CursorSdkLlmAdapter(accessToken),\n    }),\n    new SubscriptionAuthRuntime(ctx, {\n      descriptor: {\n        id: GOOGLE_ANTIGRAVITY_PROVIDER, name: 'Google Antigravity 登录兼容', method: 'browser-oauth', stability: 'experimental',\n        sourceUrl: GOOGLE_ANTIGRAVITY_AUTH_SOURCE,\n        official: false,\n      },\n      credentialRef: 'DSH_AUTH_IN_ONE_GOOGLE_ANTIGRAVITY_OAUTH',\n      adapter: new GoogleAntigravityCompatibilityAdapter(),\n      createTransport: (accessToken, credential) => new GoogleAntigravityLlmAdapter(accessToken, credential),\n    }),\n    new SubscriptionAuthRuntime(ctx, {\n      descriptor: {\n        id: KIRO_PROVIDER, name: 'Kiro 设备登录兼容', method: 'device-code', stability: 'experimental',\n        sourceUrl: KIRO_AUTH_SOURCE,\n      },\n      credentialRef: 'DSH_AUTH_IN_ONE_KIRO_OAUTH',\n      adapter: new KiroDeviceCompatibilityAdapter(),\n      createTransport: (accessToken, credential) => new KiroLlmAdapter(accessToken, credential),\n    }),\n  ]\n}\n"
