      "path": "src/host/index.ts",
      "content": "/** Provider operations and cross-session usage analytics over DSH-owned facts. */\n\nimport { Context } from '@deepseek-ai/cordis'\nimport z from '@deepseek-ai/schemastery'\nimport { TypertRemoteService, Remote } from '@deepseek-ai/dsh-typert-protocol'\nimport { credentialRef } from '@deepseek-ai/dsh-credentials'\nimport type {} from '@deepseek-ai/dsh-agent-default-model'\nimport type {} from '@deepseek-ai/dsh-session-persistence'\nimport { installSettingsSection, settingsNamespace } from '@deepseek-ai/dsh-settings'\nimport type { SettingsDescriptor } from '@deepseek-ai/dsh-settings'\n// Typert-generated ./typert and ./remote artifacts import Zod at runtime.\nimport type {} from 'zod'\nimport { foldProviderAnalytics, type SessionLogInput } from './fold.ts'\nimport {\n  KimiCodeAuthRuntime, OpenAICodexAuthRuntime, UNAVAILABLE_AUTH_PROVIDERS, createCompatibilityAuthRuntimes,\n  type CodexAuthCoordinator,\n} from './auth.ts'\nimport { PROVIDER_PLAN_PRESETS } from '../provider-plans.ts'\nimport { fetchNoRedirect, readBoundedJson } from './bounded-json.ts'\nimport { fetchAnthropicQuota, fetchAntigravityQuota, fetchCursorQuota, fetchXaiQuota } from './provider-quotas.ts'\nimport { isAuthProviderInstance, shouldProjectProviderConnection } from './provider-projection.ts'\nimport {\n  installVisionFallback,\n  listVisionRoutes,\n  resolveVisionFallbackConfig,\n  type VisionFallbackConfig,\n  type VisionFallbackView,\n} from './vision-fallback.ts'\nimport type {\n  AnalyticsQuery, AuthProviderView, CodexUsageView, ModelPriceView, OutputPriceBand, PriceOverrideRequest, ProviderAnalyticsView,\n  ProviderConnectionView, ProviderHubView, ProviderPlanPresetView, ProviderProbeView, ProviderQuotaView, SavePlanProviderRequest, SaveProviderRequest,\n} from '../types.ts'\nimport { assertCompatibleHost } from './compat-host.ts'\n\nexport type * from '../types.ts'\nexport { foldProviderAnalytics, outputPriceBandOf } from './fold.ts'\n\nconst SETTINGS_NS = settingsNamespace('auth-in-one')\nconst PI_AI_NS = settingsNamespace('llm-pi-ai')\nconst DEEPSEEK_NS = settingsNamespace('llm-deepseek')\nconst DEEPSEEK_PROVIDER = 'deepseek-official'\nconst DEEPSEEK_KEY_REF = 'DEEPSEEK_API_KEY'\nconst DEEPSEEK_PUBLIC_BASE_URL = 'https://api.deepseek.com'\nconst DEFAULT_CATALOG_VERSION = 'deepseek-usd-2026-08-14'\nconst DEEPSEEK_PRICE_SOURCE = 'https://api-docs.deepseek.com/quick_start/pricing'\nconst MAX_PROVIDER_PROBE_BYTES = 256 * 1024\n\n/** One configured catalog row before its source is attached. */\nexport interface ModelPriceConfig extends Omit<ModelPriceView, 'source'> {}\n\nconst DEFAULT_PRICES: readonly ModelPriceConfig[] = [\n  {\n    provider: DEEPSEEK_PROVIDER,\n    model: 'deepseek-v4-flash',\n    currency: 'USD',\n    sourceUrl: DEEPSEEK_PRICE_SOURCE,\n    updatedAt: '2026-08-14',\n    effectiveDate: '2026-08-14',\n    uncachedInputPerMillion: 0.14,\n    cacheReadPerMillion: 0.0028,\n    outputPerMillion: 0.28,\n  },\n  {\n    provider: DEEPSEEK_PROVIDER,\n    model: 'deepseek-v4-pro',\n    currency: 'USD',\n    sourceUrl: DEEPSEEK_PRICE_SOURCE,\n    updatedAt: '2026-08-14',\n    effectiveDate: '2026-08-14',\n    uncachedInputPerMillion: 0.435,\n    cacheReadPerMillion: 0.003625,\n    outputPerMillion: 0.87,\n  },\n]\n\n/** AuthInOne settings and composition config. */\nexport interface Config {\n  /** Version identity for the composition-owned price rows. */\n  catalogVersion?: string\n  /** Auditable composition-owned model prices. Empty means every cost is unknown until overridden. */\n  prices?: ModelPriceConfig[]\n  /** User-owned rows replacing catalog rows for an exact provider/model pair. */\n  overrides?: ModelPriceConfig[]\n  /** Optional image-description route used only for explicitly text-only main models. */\n  visionFallback?: VisionFallbackConfig\n}\n\nconst priceSchema: z<ModelPriceConfig> = z.object({\n  provider: z.string().required(),\n  model: z.string().required(),\n  currency: z.string().required(),\n  sourceUrl: z.string().required(),\n  updatedAt: z.string().required(),\n  effectiveDate: z.string().required(),\n  uncachedInputPerMillion: z.number().min(0),\n  outputPerMillion: z.number().min(0),\n  cacheReadPerMillion: z.number().min(0),\n  cacheWritePerMillion: z.number().min(0),\n  reasoningPerMillion: z.number().min(0),\n})\n\n/** Runtime validator for plugin config and its settings namespace. */\nexport const Config: z<Config> = z.object({\n  catalogVersion: z.string().default(DEFAULT_CATALOG_VERSION),\n  prices: z.array(priceSchema).default(DEFAULT_PRICES.map(price => ({ ...price }))),\n  overrides: z.array(priceSchema).default([]),\n  visionFallback: z.object({\n    enabled: z.boolean().default(false),\n    provider: z.string().default(''),\n    model: z.string().default(''),\n    maxOutputTokens: z.number().step(1).min(64).max(4_096).default(512),\n    timeoutMs: z.number().step(1).min(1_000).max(300_000).default(60_000),\n  }).default({ enabled: false, provider: '', model: '', maxOutputTokens: 512, timeoutMs: 60_000 }),\n})\n\ndeclare module '@deepseek-ai/cordis' {\n  interface Context {\n    /** Provider management and cross-session analytics service. */\n    authInOne: AuthInOneService\n  }\n}\n\nfunction isObject(value: unknown): value is Record<string, unknown> {\n  return typeof value === 'object' && value !== null && !Array.isArray(value)\n}\n\nfunction getPath(source: unknown, path: readonly string[]): unknown {\n  let value = source\n  for (const segment of path) {\n    if (!isObject(value)) return undefined\n    value = value[segment]\n  }\n  return value\n}\n\nfunction stringField(source: unknown, key: string): string | undefined {\n  if (!isObject(source)) return undefined\n  const value = source[key]\n  return typeof value === 'string' && value.length > 0 ? value : undefined\n}\n\nfunction credentialRefFor(provider: string, profile: unknown): string | undefined {\n  return stringField(profile, 'apiKeyEnv')\n    ?? (provider === DEEPSEEK_PROVIDER ? DEEPSEEK_KEY_REF : undefined)\n}\n\nfunction derivedCredentialRef(provider: string): string {\n  const normalized = provider.toUpperCase().replaceAll(/[^A-Z0-9]+/g, '_').replaceAll(/^_+|_+$/g, '')\n  return `${normalized || 'CUSTOM_PROVIDER'}_API_KEY`\n}\n\nfunction displayError(error: unknown): string {\n  if (error instanceof Error) return error.message\n  return String(error)\n}\n\nfunction assertPrice(value: PriceOverrideRequest): void {\n  for (const [name, entry] of Object.entries(value)) {\n    if (name.endsWith('PerMillion') && entry !== undefined\n      && (typeof entry !== 'number' || !Number.isFinite(entry) || entry < 0)) {\n      throw new TypeError(`${name} must be a non-negative finite number`)\n    }\n  }\n  for (const key of ['provider', 'model', 'currency', 'sourceUrl', 'updatedAt', 'effectiveDate'] as const) {\n    if (value[key].trim().length === 0) throw new TypeError(`${key} must be non-empty`)\n  }\n}\n\n/** Remote service using DSH session logs, adapters, settings, and credentials as authorities. */\nexport class AuthInOneService extends TypertRemoteService {\n  static inject = ['llm', 'sessions', 'sessionPersistence', 'agentDefaultModel', 'settings', 'credentials', 'attachments']\n  static Config = Config\n\n  private source: () => Config\n  private readonly auth: OpenAICodexAuthRuntime\n  private readonly kimiAuth: KimiCodeAuthRuntime\n  private readonly authRuntimes: readonly {\n    readonly coordinator: CodexAuthCoordinator\n    readonly models: readonly { readonly id: string; readonly name: string }[]\n    accessToken?(signal?: AbortSignal): Promise<string>\n    credential?(): Promise<import('./auth-protocol.ts').StoredOAuthCredential | undefined>\n    dispose(): void\n  }[]\n  private readonly authReady: Promise<void>\n\n  constructor(ctx: Context, config: Config = {}) {\n    super(ctx, 'authInOne')\n    assertCompatibleHost()\n    this.auth = new OpenAICodexAuthRuntime(ctx)\n    this.kimiAuth = new KimiCodeAuthRuntime(ctx)\n    this.authRuntimes = [this.auth, this.kimiAuth, ...createCompatibilityAuthRuntimes(ctx)]\n    this.authReady = Promise.all(this.authRuntimes.map(runtime => runtime.coordinator.synchronize())).then(() => undefined)\n    ctx.effect(() => () => {\n      for (const runtime of this.authRuntimes) runtime.dispose()\n    }, 'auth-in-one: managed Auth lifecycle')\n    const entry: Config = {\n      catalogVersion: config.catalogVersion ?? DEFAULT_CATALOG_VERSION,\n      prices: config.prices ?? DEFAULT_PRICES.map(price => ({ ...price })),\n      overrides: config.overrides ?? [],\n      visionFallback: resolveVisionFallbackConfig(config.visionFallback),\n    }\n    this.source = () => entry\n    installSettingsSection(ctx, SETTINGS_NS, Config, entry, {\n      setSource: current => { this.source = current },\n      onChange: () => {},\n      validate: (value) => {\n        const seen = new Set<string>()\n        for (const price of [...value.prices ?? [], ...value.overrides ?? []]) {\n          assertPrice(price)\n          const key = `${price.provider}\\u0000${price.model}`\n          if (seen.has(key) && (value.overrides ?? []).includes(price)) continue\n          if (seen.has(key)) throw new Error(`duplicate catalog price for ${price.provider}/${price.model}`)\n          seen.add(key)\n        }\n      },\n    })\n    installVisionFallback(ctx, () => this.source().visionFallback)\n  }\n\n  private descriptors(): Map<string, SettingsDescriptor> {\n    return new Map(this.ctx.settings.describe().map(entry => [String(entry.ns), entry]))\n  }\n\n  private authRuntime(provider: string): typeof this.authRuntimes[number] | undefined {\n    return this.authRuntimes.find(runtime => runtime.coordinator.snapshot().id === provider)\n  }\n\n  private prices(): ModelPriceView[] {\n    const settings = this.source()\n    const merged = new Map<string, ModelPriceView>()\n    for (const row of settings.prices ?? []) {\n      merged.set(`${row.provider}\\u0000${row.model}`, { ...row, source: 'catalog' })\n    }\n    for (const row of settings.overrides ?? []) {\n      merged.set(`${row.provider}\\u0000${row.model}`, { ...row, source: 'user' })\n    }\n    return [...merged.values()]\n  }\n\n  private async logs(signal?: AbortSignal): Promise<SessionLogInput[]> {\n    const live = new Map(this.ctx.sessions.list().map(session => [String(session.id), session]))\n    const logs: SessionLogInput[] = []\n    for (const header of await this.ctx.sessionPersistence.list(signal)) {\n      signal?.throwIfAborted()\n      const session = live.get(String(header.id))\n      if (session !== undefined) {\n        logs.push({ header: session.header, events: session.events })\n        live.delete(String(header.id))\n        continue\n      }\n      const stored = await this.ctx.sessionPersistence.inspect(header.id, signal)\n      logs.push({ header: stored.meta, events: stored.events })\n    }\n    for (const session of live.values()) logs.push({ header: session.header, events: session.events })\n    return logs\n  }\n\n  /** Read cross-session provider usage from live and persisted DSH logs. */\n  @Remote('analytics')\n  async analytics(query: AnalyticsQuery, signal: AbortSignal): Promise<ProviderAnalyticsView> {\n    const bands: readonly OutputPriceBand[] = ['all', '0-1', '1-5', '5-15', '15-plus', 'unpriced']\n    if (!bands.includes(query.outputPriceBand)) {\n      throw new TypeError(`unsupported output price band ${JSON.stringify(query.outputPriceBand)}`)\n    }\n    if (query.provider !== null && query.provider.length === 0) throw new TypeError('provider filter must be null or non-empty')\n    const settings = this.source()\n    return foldProviderAnalytics(\n      await this.logs(signal),\n      query,\n      this.prices(),\n      settings.catalogVersion ?? DEFAULT_CATALOG_VERSION,\n    )\n  }\n\n  /** Read provider routes, connection state, models, and the future-Agent default. */\n  @Remote('providers')\n  async providers(): Promise<ProviderHubView> {\n    await this.authReady\n    await Promise.all(this.authRuntimes.map(runtime => runtime.coordinator.synchronize()))\n    const active = new Map(this.ctx.llm.listProviders().map(provider => [provider.id, provider]))\n    const configurable = new Map(this.ctx.llm.listConfigurableProviders().map(provider => [provider.provider, provider]))\n    const authInstances = this.authRuntimes\n      .map(runtime => runtime.coordinator.snapshot())\n      .filter(auth => isAuthProviderInstance(auth.status))\n    const ids = [...new Set([\n      ...configurable.keys(),\n      ...active.keys(),\n      ...authInstances.map(auth => auth.id),\n    ])]\n    const descriptors = this.descriptors()\n    const candidates = await Promise.all(ids.map(async (id): Promise<ProviderConnectionView | null> => {\n      const live = active.get(id)\n      const entry = configurable.get(id)\n      const descriptor = entry === undefined ? undefined : descriptors.get(entry.settingsNs)\n      const profile = entry === undefined ? undefined : getPath(descriptor?.value, entry.settingsPath)\n      const runtime = this.authRuntime(id)\n      const authCatalog = runtime?.coordinator.snapshot()\n      const auth = authCatalog !== undefined && isAuthProviderInstance(authCatalog.status) ? authCatalog : undefined\n      if (!shouldProjectProviderConnection({\n        provider: id,\n        hasLiveRoute: live !== undefined,\n        hasProfile: profile !== undefined,\n        authStatus: auth?.status ?? null,\n      })) return null\n      const ref = credentialRefFor(id, profile)\n      const credential = ref === undefined ? undefined : await this.ctx.credentials.describe(credentialRef(ref))\n      let models: ProviderConnectionView['models'] = []\n      let modelError: string | null = null\n      if (live !== undefined) {\n        try {\n          models = (await this.ctx.llm.listModels(id)).map(model => ({ id: model.id, name: model.name }))\n        } catch (error) {\n          modelError = displayError(error)\n        }\n      }\n      if (auth !== undefined && models.length === 0) models = [...runtime!.models]\n      return {\n        id,\n        name: live?.name ?? entry?.displayName ?? auth?.name ?? id,\n        active: live !== undefined,\n        configurable: entry !== undefined,\n        declared: entry?.declared === true,\n        configured: auth === undefined ? profile !== undefined : auth.status === 'connected',\n        credentialConfigured: auth === undefined\n          ? credential?.configured ?? (ref === undefined ? null : false)\n          : auth.status === 'connected',\n        credentialWritable: auth === undefined\n          ? credential?.writable ?? (ref === undefined ? null : false)\n          : true,\n        authMode: auth === undefined ? 'api-key-only' : 'oauth',\n        accessType: auth !== undefined ? 'account-auth' : entry?.declared === true ? 'custom-api' : 'api',\n        accountLabel: auth?.accountLabel ?? null,\n        settingsNs: entry?.settingsNs ?? null,\n        baseURL: stringField(profile, 'baseURL') ?? (id === DEEPSEEK_PROVIDER ? DEEPSEEK_PUBLIC_BASE_URL : null),\n        models,\n        modelError,\n      }\n    }))\n    const providers = candidates.filter((provider): provider is ProviderConnectionView => provider !== null)\n    const selection = this.ctx.agentDefaultModel.currentSelection()\n    return {\n      generatedAt: Date.now(),\n      defaultSelection: {\n        provider: selection.provider,\n        model: selection.model,\n        ...selection.reasoningEffort === undefined ? {} : { reasoningEffort: String(selection.reasoningEffort) },\n      },\n      providers,\n    }\n  }\n\n  /** List browser-safe official account-login states. */\n  @Remote('authProviders')\n  async authProviders(): Promise<readonly AuthProviderView[]> {\n    await this.authReady\n    return [...await Promise.all(this.authRuntimes.map(runtime => runtime.coordinator.synchronize())), ...UNAVAILABLE_AUTH_PROVIDERS]\n  }\n\n  /** Read the allowlisted vendor API and subscription-key presets. */\n  @Remote('planProviders')\n  planProviders(): readonly ProviderPlanPresetView[] {\n    return PROVIDER_PLAN_PRESETS\n  }\n\n  /** Read OpenAI Codex subscription windows without exposing the bearer credential. */\n  @Remote('codexUsage')\n  async codexUsage(signal: AbortSignal): Promise<CodexUsageView> {\n    await this.authReady\n    return this.auth.usage(signal)\n  }\n\n  /** Read all implemented subscription quota windows without exposing credentials. */\n  @Remote('providerQuotas')\n  async providerQuotas(signal: AbortSignal): Promise<readonly ProviderQuotaView[]> {\n    await this.authReady\n    const codex = await this.auth.usage(signal)\n    const codexQuota: ProviderQuotaView = {\n      provider: 'openai-codex',\n      status: codex.status,\n      generatedAt: codex.generatedAt,\n      bestEffort: true,\n      sourceUrl: codex.sourceUrl,\n      windows: codex.windows.map(window => ({\n        id: window.id,\n        label: window.id === 'primary' ? 'Primary window' : 'Secondary window',\n        usedPercent: window.usedPercent,\n        remainingPercent: window.remainingPercent,\n        windowSeconds: window.windowSeconds,\n        resetAt: window.resetAt,\n      })),\n      error: codex.error,\n    }\n    const compatibility = await Promise.all(this.authRuntimes.flatMap(runtime => {\n      if (runtime.accessToken === undefined) return []\n      const provider = runtime.coordinator.snapshot().id\n      if (!['xai', 'anthropic', 'cursor', 'google-antigravity'].includes(provider)) return []\n      return [(async (): Promise<ProviderQuotaView> => {\n        let token: string\n        try {\n          token = await runtime.accessToken!(signal)\n        } catch {\n          return {\n            provider, status: 'signed-out', generatedAt: Date.now(), bestEffort: true,\n            sourceUrl: runtime.coordinator.snapshot().sourceUrl, windows: [], error: null,\n          }\n        }\n        if (provider === 'xai') return fetchXaiQuota(token, signal)\n        if (provider === 'anthropic') return fetchAnthropicQuota(token, signal)\n        if (provider === 'cursor') return fetchCursorQuota(token, signal)\n        const credential = await runtime.credential!()\n        return credential === undefined\n          ? {\n              provider, status: 'signed-out', generatedAt: Date.now(), bestEffort: true,\n              sourceUrl: runtime.coordinator.snapshot().sourceUrl, windows: [], error: null,\n            }\n          : fetchAntigravityQuota(token, credential, signal)\n      })()]\n    }))\n    return [codexQuota, await this.kimiAuth.quota(signal), ...compatibility]\n  }\n\n  /** Begin the official OpenAI Codex browser OAuth flow on the Host. */\n  @Remote('startAuth')\n  async startAuth(provider: string): Promise<AuthProviderView> {\n    await this.authReady\n    const runtime = this.authRuntime(provider)\n    if (runtime === undefined) throw new TypeError(`unsupported Auth provider ${provider}`)\n    return runtime.coordinator.start()\n  }\n\n  /** Cancel one plugin-local OAuth attempt without affecting stored credentials. */\n  @Remote('cancelAuth')\n  async cancelAuth(provider: string, attemptId: string): Promise<AuthProviderView> {\n    await this.authReady\n    const runtime = this.authRuntime(provider)\n    if (runtime === undefined) throw new TypeError(`unsupported Auth provider ${provider}`)\n    return runtime.coordinator.cancel(attemptId)\n  }\n\n  /** Submit a one-time authorization value to the matching Host transaction. */\n  @Remote('submitAuth')\n  async submitAuth(provider: string, attemptId: string, value: string): Promise<AuthProviderView> {\n    await this.authReady\n    const runtime = this.authRuntime(provider)\n    if (runtime === undefined) throw new TypeError(`unsupported Auth provider ${provider}`)\n    return runtime.coordinator.submit(attemptId, value)\n  }\n\n  /** Sign out and remove one Host-only account credential. */\n  @Remote('logoutAuth')\n  async logoutAuth(provider: string): Promise<AuthProviderView> {\n    await this.authReady\n    const runtime = this.authRuntime(provider)\n    if (runtime === undefined) throw new TypeError(`unsupported Auth provider ${provider}`)\n    return runtime.coordinator.logout()\n  }\n\n  /** Save an OpenAI-compatible route or edit the official DeepSeek route. */\n  @Remote('saveProvider')\n  async saveProvider(request: SaveProviderRequest): Promise<void> {\n    const provider = request.provider.trim()\n    const displayName = request.displayName.trim()\n    const baseURL = request.baseURL.trim().replace(/\\/+$/, '')\n    if (!/^[a-z0-9][a-z0-9._-]*$/i.test(provider)) throw new TypeError('provider must be a stable route id')\n    if (displayName.length === 0) throw new TypeError('displayName must be non-empty')\n    if (!URL.canParse(baseURL) || !baseURL.startsWith('http')) throw new TypeError('baseURL must be an HTTP(S) URL')\n    if (request.models.length === 0) throw new TypeError('at least one model is required')\n    for (const model of request.models) {\n      if (model.id.trim().length === 0) throw new TypeError('model ids must be non-empty')\n    }\n\n    const directory = this.ctx.llm.listConfigurableProviders().find(entry => entry.provider === provider)\n    const settingsNs = settingsNamespace(directory?.settingsNs ?? String(PI_AI_NS))\n    const settingsPath = directory?.settingsPath ?? ['providers', provider]\n    const current = getPath(this.ctx.settings.get(settingsNs), settingsPath)\n    const keyRef = credentialRefFor(provider, current) ?? derivedCredentialRef(provider)\n    if (settingsNs === DEEPSEEK_NS) {\n      await this.ctx.settings.mutate(settingsNs, [\n        { op: 'set', path: ['baseURL'], value: baseURL },\n        { op: 'set', path: ['models'], value: request.models },\n        { op: 'set', path: ['apiKeyEnv'], value: keyRef },\n      ])\n    } else {\n      await this.ctx.settings.mutate(settingsNs, [{\n        op: 'set',\n        path: settingsPath,\n        value: {\n          apiKeyEnv: keyRef,\n          displayName,\n          api: request.api ?? 'openai-completions',\n          baseURL,\n          models: request.models,\n          ...request.headers === undefined ? {} : { headers: request.headers },\n        },\n      }])\n    }\n    if (request.apiKey !== undefined) {\n      const apiKey = request.apiKey.trim()\n      if (apiKey.length === 0) throw new TypeError('apiKey must be non-empty when supplied')\n      await this.ctx.credentials.set(credentialRef(keyRef), apiKey)\n    }\n  }\n\n  /** Save one allowlisted vendor preset while keeping its API key write-only. */\n  @Remote('savePlanProvider')\n  async savePlanProvider(request: SavePlanProviderRequest): Promise<void> {\n    const preset = PROVIDER_PLAN_PRESETS.find(entry => entry.id === request.presetId)\n    if (preset === undefined) throw new TypeError(`unsupported Provider preset ${request.presetId}`)\n    await this.saveProvider({\n      provider: preset.provider,\n      displayName: preset.name,\n      baseURL: preset.baseURL,\n      api: preset.api,\n      apiKey: request.apiKey,\n      models: preset.models.map(model => ({ id: model.id, name: model.name })),\n    })\n  }\n\n  /** Probe the configured OpenAI-compatible `/models` endpoint without exposing credentials. */\n  @Remote('probe')\n  async probe(provider: string, signal: AbortSignal): Promise<ProviderProbeView> {\n    const startedAt = performance.now()\n    try {\n      const auth = this.authRuntime(provider)?.coordinator.snapshot()\n      if (auth !== undefined && isAuthProviderInstance(auth.status)) {\n        const models = (await this.ctx.llm.listModels(provider)).map(model => model.id)\n        return { ok: true, latencyMs: Math.round(performance.now() - startedAt), models, error: null }\n      }\n      const directory = this.ctx.llm.listConfigurableProviders().find(entry => entry.provider === provider)\n      if (directory === undefined) throw new Error('provider does not expose editable connection metadata')\n      const profile = getPath(this.ctx.settings.get(settingsNamespace(directory.settingsNs)), directory.settingsPath)\n      const baseURL = stringField(profile, 'baseURL') ?? (provider === DEEPSEEK_PROVIDER ? DEEPSEEK_PUBLIC_BASE_URL : undefined)\n      if (baseURL === undefined) throw new Error('provider has no HTTP base URL to test')\n      const ref = credentialRefFor(provider, profile)\n      const resolved = ref === undefined ? undefined : await this.ctx.credentials.resolve(credentialRef(ref))\n      const configuredHeaders = isObject(profile) && isObject(profile.headers)\n        ? Object.fromEntries(Object.entries(profile.headers).filter((entry): entry is [string, string] => typeof entry[1] === 'string'))\n        : {}\n      const api = stringField(profile, 'api') ?? 'openai-completions'\n      const hasCredentialHeader = Object.keys(configuredHeaders).some(key => {\n        const lower = key.toLowerCase()\n        return lower === 'authorization' || lower === 'x-api-key'\n      })\n      const headers = {\n        accept: 'application/json',\n        ...configuredHeaders,\n        ...api === 'anthropic-messages' ? { 'anthropic-version': '2023-06-01' } : {},\n        ...resolved === undefined || hasCredentialHeader ? {} : api === 'anthropic-messages'\n          ? { 'x-api-key': resolved.value }\n          : { authorization: `Bearer ${resolved.value}` },\n      }\n      const modelsUrl = api === 'anthropic-messages'\n        ? `${baseURL.replace(/\\/+$/, '')}/v1/models`\n        : `${baseURL.replace(/\\/+$/, '')}/models`\n      const response = await fetchNoRedirect(modelsUrl, { headers, signal })\n      if (!response.ok) throw new Error(`provider returned HTTP ${String(response.status)}`)\n      const body = await readBoundedJson(response, MAX_PROVIDER_PROBE_BYTES)\n      const data = isObject(body) && Array.isArray(body.data) ? body.data : []\n      const models = data.flatMap((item) => isObject(item) && typeof item.id === 'string' ? [item.id] : []).slice(0, 200)\n      return { ok: true, latencyMs: Math.round(performance.now() - startedAt), models, error: null }\n    } catch (error) {\n      if (signal.aborted) throw error\n      return { ok: false, latencyMs: Math.round(performance.now() - startedAt), models: [], error: displayError(error) }\n    }\n  }\n\n  /** Save the model selection used for future Agents. */\n  @Remote('saveDefault')\n  async saveDefault(provider: string, model: string): Promise<void> {\n    await this.ctx.llm.resolveModelInfo(provider, model)\n    await this.ctx.agentDefaultModel.saveSelection({ provider, model })\n  }\n\n  /** Read the optional fallback and routes whose adapters explicitly declare image input. */\n  @Remote('visionFallback')\n  async visionFallback(): Promise<VisionFallbackView> {\n    const value = resolveVisionFallbackConfig(this.source().visionFallback)\n    const providers = (await this.providers()).providers.map(provider => ({\n      id: provider.id,\n      name: provider.name,\n      active: provider.active,\n      configured: provider.configured,\n      credentialConfigured: provider.credentialConfigured,\n      accessType: provider.accessType,\n      accountLabel: provider.accountLabel,\n    }))\n    const routes = await listVisionRoutes(this.ctx, providers)\n    return {\n      ...value,\n      selectionAvailable: !value.enabled || routes.some(route => route.provider === value.provider && route.model === value.model),\n      routes,\n    }\n  }\n\n  /** Save the fallback without ever accepting a credential or image payload. */\n  @Remote('saveVisionFallback')\n  async saveVisionFallback(request: VisionFallbackConfig): Promise<void> {\n    const value = resolveVisionFallbackConfig(request)\n    if (value.enabled) {\n      if (value.provider.length === 0 || value.model.length === 0) {\n        throw new TypeError('enabled vision fallback requires a Provider and model')\n      }\n      const info = await this.ctx.llm.resolveModelInfo(value.provider, value.model)\n      if (info.inputModalities?.includes('image') !== true) {\n        throw new TypeError('vision fallback model must explicitly declare image input')\n      }\n    }\n    await this.ctx.settings.mutate(SETTINGS_NS, [{ op: 'set', path: ['visionFallback'], value }])\n  }\n\n  /** Add or replace one durable user-owned price row. */\n  @Remote('savePriceOverride')\n  async savePriceOverride(request: PriceOverrideRequest): Promise<void> {\n    assertPrice(request)\n    const current = this.source().overrides ?? []\n    const next = current.filter(row => row.provider !== request.provider || row.model !== request.model)\n    next.push({ ...request })\n    await this.ctx.settings.mutate(SETTINGS_NS, [{ op: 'set', path: ['overrides'], value: next }])\n  }\n}\n\nexport default AuthInOneService\n"
