      "path": "src/host/auth-store.ts",
      "content": "/** OAuth credential persistence and refresh coordination over DSH credentials. */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport { credentialRef } from '@deepseek-ai/dsh-credentials'\nimport {\n  AuthProtocolError,\n  credentialGeneration,\n  type AuthProviderAdapter,\n  type StoredOAuthCredential,\n} from './auth-protocol.ts'\n\nconst OPENAI_CODEX_CREDENTIAL_REF = credentialRef('DSH_AUTH_IN_ONE_OPENAI_CODEX_OAUTH')\nconst REFRESH_EARLY_MS = 60 * 1000\n\nfunction parseCredential(value: string): StoredOAuthCredential {\n  let parsed: unknown\n  try {\n    parsed = JSON.parse(value)\n  } catch {\n    throw new AuthProtocolError('invalid-response')\n  }\n  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {\n    throw new AuthProtocolError('invalid-response')\n  }\n  const row = parsed as Record<string, unknown>\n  const providerData = row.providerData\n  const validProviderData = providerData === undefined || (\n    typeof providerData === 'object' && providerData !== null && !Array.isArray(providerData)\n    && Object.entries(providerData).every(([key, entry]) => key.length > 0 && key.length <= 64 && (\n      typeof entry === 'string' || typeof entry === 'number' || typeof entry === 'boolean'\n      || (Array.isArray(entry) && entry.length <= 512 && entry.every(item => typeof item === 'string'))\n    ))\n  )\n  if (row.version !== 1\n    || typeof row.accessToken !== 'string' || row.accessToken.length === 0\n    || typeof row.refreshToken !== 'string' || row.refreshToken.length === 0\n    || typeof row.expiresAt !== 'number' || !Number.isFinite(row.expiresAt)\n    || (row.accountId !== undefined && typeof row.accountId !== 'string')\n    || (row.email !== undefined && typeof row.email !== 'string')\n    || !validProviderData\n    || (row.needsReauth !== undefined && row.needsReauth !== true)) {\n    throw new AuthProtocolError('invalid-response')\n  }\n  return parsed as StoredOAuthCredential\n}\n\n/** Store status safe for Host state projection after identity masking. */\nexport interface AuthCredentialStatus {\n  readonly connected: boolean\n  readonly needsReauth: boolean\n  readonly email?: string\n  readonly accountId?: string\n}\n\n/** Serializes DSH credential writes and deduplicates refresh for one Provider. */\nexport class DshOAuthCredentialStore {\n  private mutation = Promise.resolve<unknown>(undefined)\n  private refreshFlight: Promise<StoredOAuthCredential> | undefined\n  private readonly ref\n\n  constructor(private readonly ctx: Context, name = 'DSH_AUTH_IN_ONE_OPENAI_CODEX_OAUTH') {\n    this.ref = name === 'DSH_AUTH_IN_ONE_OPENAI_CODEX_OAUTH'\n      ? OPENAI_CODEX_CREDENTIAL_REF\n      : credentialRef(name)\n  }\n\n  async read(): Promise<StoredOAuthCredential | undefined> {\n    const resolved = await this.ctx.credentials.resolve(this.ref)\n    return resolved === undefined ? undefined : parseCredential(resolved.value)\n  }\n\n  private enqueue<T>(task: () => Promise<T>): Promise<T> {\n    const next = this.mutation.catch(() => undefined).then(task)\n    this.mutation = next.catch(() => undefined)\n    return next\n  }\n\n  write(credential: StoredOAuthCredential): Promise<void> {\n    return this.enqueue(() => this.ctx.credentials.set(this.ref, JSON.stringify(credential)))\n  }\n\n  delete(): Promise<void> {\n    return this.enqueue(() => this.ctx.credentials.unset(this.ref))\n  }\n\n  async status(): Promise<AuthCredentialStatus> {\n    const credential = await this.read()\n    if (credential === undefined) return { connected: false, needsReauth: false }\n    return {\n      connected: credential.needsReauth !== true,\n      needsReauth: credential.needsReauth === true,\n      ...credential.email === undefined ? {} : { email: credential.email },\n      ...credential.accountId === undefined ? {} : { accountId: credential.accountId },\n    }\n  }\n\n  /** Return a fresh access token, rotating the stored refresh token at most once per generation. */\n  async accessToken(adapter: AuthProviderAdapter, signal?: AbortSignal): Promise<string> {\n    const current = await this.read()\n    if (current === undefined || current.needsReauth === true) throw new AuthProtocolError('refresh-rejected')\n    if (current.expiresAt > Date.now() + REFRESH_EARLY_MS) return current.accessToken\n    if (this.refreshFlight !== undefined) return (await this.refreshFlight).accessToken\n    const startedGeneration = credentialGeneration(current)\n    const refresh = (async (): Promise<StoredOAuthCredential> => {\n      let fresh: StoredOAuthCredential\n      try {\n        fresh = await adapter.refresh(current, signal)\n      } catch (error) {\n        if (error instanceof AuthProtocolError && error.category === 'refresh-rejected') {\n          await this.enqueue(async () => {\n            const stored = await this.read()\n            if (stored === undefined || credentialGeneration(stored) !== startedGeneration) return\n            await this.ctx.credentials.set(this.ref, JSON.stringify({ ...stored, needsReauth: true }))\n          })\n        }\n        throw error\n      }\n      return this.enqueue(async () => {\n        const stored = await this.read()\n        if (stored === undefined) throw new AuthProtocolError('cancelled')\n        if (credentialGeneration(stored) !== startedGeneration) {\n          if (stored.needsReauth !== true && stored.expiresAt > Date.now() + REFRESH_EARLY_MS) return stored\n          throw new AuthProtocolError('refresh-rejected')\n        }\n        await this.ctx.credentials.set(this.ref, JSON.stringify(fresh))\n        return fresh\n      })\n    })().finally(() => {\n      if (this.refreshFlight === refresh) this.refreshFlight = undefined\n    })\n    this.refreshFlight = refresh\n    return (await refresh).accessToken\n  }\n}\n"
    }
  ],
